import { Component, EventEmitter, Event, h, State, Prop } from '@stencil/core';

@Component({
  tag: 'std-upload-file',
  styleUrl: 'std-upload-file.css',
  shadow: true
})
export class StdUploadFile {
  @Event() fileSelected: EventEmitter<{ data: { file: File; errors: string[] }[]; source: string }>;
  @State() isDragging = false;

  @Prop() messageUpload = 'Los archivos no deben exceder 8 MB y sólo se admiten formatos txt.';
  @Prop({ mutable: true }) selectedFiles: { name: string; size: number }[] | null = null;
  @Prop() validationMode: 'mimeType' | 'extension' | 'both' = 'extension';
  @Prop() limit: number | null = null;
  @Prop() accept: string[] = [];
  @Prop() multiple = false;
  @Prop() limitName: number = 50;
  @Prop() showDetail: boolean = false;
  @Prop() fileNamePattern: string; // ^[a-zA-Z0-9._\\- ]+$
  @Prop() status: string;
  @Prop() classes: string;

  @Prop() headerValidation: boolean = false;
  @State() newFile: File;
  @State() signsMap: { [key: string]: number[] } = {
    jpg: [0xff, 0xd8, 0xff],
    png: [0x89, 0x50, 0x4e, 0x47],
    pdf: [0x25, 0x50, 0x44, 0x46],
    docx: [0x50, 0x4b, 0x03, 0x04],
    bmp: [0x42, 0x4d],
    mp3: [0x49, 0x44, 0x33]
  };

  inputFileElement: HTMLInputElement;

  private sanitizer(filename: string) {
    let decoded = '';
    try {
      decoded = decodeURIComponent(filename);
    } catch (error) {
      decoded = filename;
    }

    decoded.normalize('NFC');
    decoded = decoded.replace(/[^\w.\-]/g, '');

    let parts = decoded.split('.');
    const filenameshort = parts[0].slice(0, this.limitName);
    decoded = parts.length > 1 ? filenameshort + '.' + parts[parts.length - 1] : filenameshort;

    return decoded;
  }

  async checkFileHeaders(file: File, fileExt: string): Promise<boolean> {
    const distincMap = structuredClone(this.signsMap);
    delete distincMap[fileExt];

    try {
      const arrayBuffer = await file.slice(0, 4).arrayBuffer();
      const bytes = new Uint8Array(arrayBuffer);

      for (const kl of Object.keys(distincMap)) {
        const validateBytes = distincMap[kl].every((e, i) => e === bytes[i]);
        if (validateBytes) {
          return true; // file forbidden
        }
      }

      return false;
    } catch (error) {
      console.error(error);
      return true; // if has error reject process
    }
  }

  async validateFile(file: File) {
    const errors: string[] = [];
    this.newFile = file;

    if (!file) {
      errors.push('INVALID_FILE');
      return errors;
    }

    const fileExtension = file.name.split('.').pop()?.toLowerCase() || '';
    const nameFileWithoutExtension = file.name.split('.').slice(0, -1).join('.');

    // validate file headers if is a file genuine
    if (this.headerValidation) {
      const isCorrupted = await this.checkFileHeaders(file, fileExtension);
      if (isCorrupted) {
        errors.push('INVALID_FILE');
      }
    }

    if (this.fileNamePattern && !new RegExp(this.fileNamePattern).test(nameFileWithoutExtension)) {
      errors.push('INVALID_FILENAME');
    }

    if (this.accept.length > 0 && ['extension', 'both'].includes(this.validationMode) && (!fileExtension || !this.accept.includes(`.${fileExtension}`))) {
      errors.push('INVALID_EXTENSION');
    }

    if (this.accept.length > 0 && ['mimeType', 'both'].includes(this.validationMode) && !this.accept.includes(file.type)) {
      errors.push('INVALID_TYPE');
    }

    if (this.limit && file.size > this.limit) {
      errors.push('INVALID_SIZE');
    }

    // rename filename
    // mandatory for security
    if (errors.length === 0) {
      const fileName = this.sanitizer(file.name || '');
      const blob = file.slice(0, file.size, file.type);
      this.newFile = new File([blob], fileName, { type: file.type });
    }

    return errors;
  }

  private async processFiles(files: FileList | File[], source: string) {
    const fileArray = Array.from(files);
    const data = await Promise.all(
      fileArray.map(async file => {
        const errors = await this.validateFile(file);
        return { file: errors.length > 0 ? null : this.newFile, errors };
      })
    );

    this.fileSelected.emit({ data, source });

    this.selectedFiles = data
      .filter(entry => entry.errors.length === 0)
      .map(entry => (entry.file ? { name: entry.file.name, size: entry.file.size } : null))
      .filter(Boolean) as { name: string; size: number }[];

    this.inputFileElement.value = null;
  }

  private handleFileInput(event: Event) {
    const files = (event.target as HTMLInputElement).files;
    if (files && files.length > 0 && this.status !== 'disabled') {
      this.processFiles(files, 'input');
    }
  }

  private handleDrop(event: DragEvent) {
    event.preventDefault();
    this.isDragging = false;
    const files = event.dataTransfer?.files || [];
    if (files && files.length > 0 && this.status !== 'disabled') {
      this.processFiles(files, 'drop');
    }
  }

  private handleDragOver(event: DragEvent) {
    if (this.status === 'disabled') return;
    event.preventDefault();
    this.isDragging = true;
  }

  private handleDragLeave() {
    this.isDragging = false;
  }

  private invokeInput() {
    if (this.status === 'disabled') return;
    this.inputFileElement.click();
  }

  render() {
    const statusClasses = {
      disabled: 'disabled'
    }[this.status];

    const uploadClasses = ['css-upload-file', statusClasses, this.classes].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class={uploadClasses}>
        <div class="hidden lg:flex flex-col gap-2">
          <div
            class={`border border-dashed rounded-lg p-6 flex flex-col gap-2 justify-center items-center ${this.isDragging ? 'border-alternative' : 'border-border-default'}`}
            onDrop={event => this.handleDrop(event)}
            onDragOver={event => this.handleDragOver(event)}
            onDragLeave={() => this.handleDragLeave()}>
            <label
              class={`bg-primary text-white rounded-full flex justify-center items-center p-3  uploadFile-button ${
                this.status === 'disabled' ? 'cursor-default' : 'cursor-pointer'
              }`}>
              <i class="icon-attach-document text-2xl leading-none uploadFile-button-icon"></i>
              <input
                ref={el => (this.inputFileElement = el)}
                type="file"
                disabled={this.status === 'disabled'}
                accept={this.accept.join(',')}
                multiple={this.multiple}
                class="hidden"
                onChange={event => this.handleFileInput(event)}
              />
            </label>
            <p class="text-dark text-sm uploadFile-text">Seleccionar o arrastrar el archivo para cargar</p>
            {this.showDetail && this.selectedFiles && this.selectedFiles.length > 0 && (
              <div class="text-dark text-sm mt-2">
                {this.selectedFiles.map(file => (
                  <div key={file.name}>
                    <p>Archivo: {file.name}</p>
                    <p>Tamaño: {(file.size / 1024).toFixed(2)} KB</p>
                  </div>
                ))}
              </div>
            )}
          </div>
          <p class="text-dark text-xs uploadFile-text">{this.messageUpload}</p>
        </div>

        <div class="flex lg:hidden flex-col gap-4">
          <div class="flex flex-col gap-2">
            <h4 class="text-lg font-bold">Subir archivos</h4>
            <p class={`text-sm ${this.status === 'disabled' ? 'text-labeldisabled' : ''}`}>{this.messageUpload}</p>
          </div>
          <div class="w-36">
            <std-button disabled={this.status === 'disabled'} label="Subir" onClick={() => this.invokeInput()} />
          </div>
        </div>
      </div>
    );
  }
}
